/*
  ============================================================
  GRASSBOT ESP32 - FINAL SAFE MOTOR CONTROLLER
  ============================================================

  PINS FIXED TO MATCH ACTUAL HARDWARE:

  DRIVER 1 (LEFT):
    L_ENA  = GPIO 14
    L_IN1  = GPIO 27
    L_IN2  = GPIO 26
    L_ENB  = GPIO 25
    L_IN3  = GPIO 33
    L_IN4  = GPIO 32

  DRIVER 2 (RIGHT):
    R_ENA  = GPIO 5
    R_IN1  = GPIO 16
    R_IN2  = GPIO 17
    R_ENB  = GPIO 18
    R_IN3  = GPIO 19
    R_IN4  = GPIO 21

  RELAY  = GPIO 13

  ULTRASONIC:
    FRONT TRIG = GPIO 4   ECHO = GPIO 34 (voltage divider)
    LEFT  TRIG = GPIO 2   ECHO = GPIO 35 (voltage divider)
    RIGHT TRIG = GPIO 15  ECHO = GPIO 39 (VN pin, voltage divider)

  Commands from Raspberry Pi:
      PING / STATUS
      FORWARD / BACKWARD / REVERSE / LEFT / RIGHT
      STOP / MOVE_STOP / ESTOP
      BLADE_ON / BLADE_OFF
      SET_SPEED 0-100

  Safety:
      - Motors STOP at boot
      - Blade OFF at boot
      - STOP always turns blade OFF
      - ESTOP always turns blade OFF
      - Watchdog stops robot if Pi disconnects
      - Ultrasonic obstacle stops motors and blade
      - Robot ALWAYS stops before changing direction
      - Blade cannot turn ON while stopped
      - Blade cannot turn ON when obstacle is close
  ============================================================
*/

// ============================================================
// MOTOR DRIVER 1 - LEFT SIDE (FIXED PINS)
// ============================================================
#define L_ENA   14
#define L_IN1   27
#define L_IN2   26

#define L_ENB   25
#define L_IN3   33
#define L_IN4   32

// ============================================================
// MOTOR DRIVER 2 - RIGHT SIDE (FIXED PINS)
// ============================================================
#define R_ENA   5
#define R_IN1   16
#define R_IN2   17

#define R_ENB   18
#define R_IN3   19
#define R_IN4   21

// ============================================================
// BLADE RELAY
// ============================================================
#define RELAY_PIN 13

// ============================================================
// ULTRASONIC SENSORS (FIXED PINS)
// ============================================================
#define FRONT_TRIG  4
#define FRONT_ECHO  34   // voltage divider: 1k+2k

#define LEFT_TRIG   2
#define LEFT_ECHO   35   // voltage divider: 1k+2k

#define RIGHT_TRIG  15
#define RIGHT_ECHO  39   // VN pin, voltage divider: 1k+2k

// ============================================================
// SETTINGS
// ============================================================
int motorSpeed = 160;

const unsigned long DIRECTION_CHANGE_DELAY = 500;
const unsigned long REVERSE_DELAY          = 700;

const float FRONT_STOP_DISTANCE = 35.0;
const float SIDE_STOP_DISTANCE  = 25.0;

const unsigned long ULTRASONIC_TIMEOUT  = 25000;
const unsigned long PI_WATCHDOG_TIMEOUT = 2000;

// ============================================================
// ROBOT STATE
// ============================================================
enum MotionState { STOPPED, FORWARD, BACKWARD, LEFT, RIGHT };
MotionState currentMotion = STOPPED;

bool bladeOn = false;
unsigned long lastPiCommand = 0;

struct UltrasonicData {
  float front;
  float left;
  float right;
};

// ============================================================
// SETUP
// ============================================================
void setup() {
  Serial.begin(115200);

  // Motor output pins
  pinMode(L_IN1, OUTPUT); pinMode(L_IN2, OUTPUT);
  pinMode(L_IN3, OUTPUT); pinMode(L_IN4, OUTPUT);
  pinMode(R_IN1, OUTPUT); pinMode(R_IN2, OUTPUT);
  pinMode(R_IN3, OUTPUT); pinMode(R_IN4, OUTPUT);

  // Relay
  pinMode(RELAY_PIN, OUTPUT);

  // Ultrasonic
  pinMode(FRONT_TRIG, OUTPUT); pinMode(FRONT_ECHO, INPUT);
  pinMode(LEFT_TRIG,  OUTPUT); pinMode(LEFT_ECHO,  INPUT);
  pinMode(RIGHT_TRIG, OUTPUT); pinMode(RIGHT_ECHO, INPUT);

  // PWM (ESP32 Core 3.x)
  ledcAttach(L_ENA, 1000, 8);
  ledcAttach(L_ENB, 1000, 8);
  ledcAttach(R_ENA, 1000, 8);
  ledcAttach(R_ENB, 1000, 8);

  // Safe start
  stopMotors();
  bladeOff();
  currentMotion = STOPPED;
  lastPiCommand = millis();

  Serial.println();
  Serial.println("====================================");
  Serial.println("       GRASSBOT ESP32 READY");
  Serial.println("====================================");
  Serial.println("Driver 1 LEFT:  GPIO 14,27,26,25,33,32");
  Serial.println("Driver 2 RIGHT: GPIO 5,16,17,18,19,21");
  Serial.println("Relay: GPIO 13");
  Serial.println("US Front: TRIG=4  ECHO=34");
  Serial.println("US Left:  TRIG=2  ECHO=35");
  Serial.println("US Right: TRIG=15 ECHO=39");
  Serial.println("Motors: SAFE");
  Serial.println("Blade: OFF");
  Serial.println("====================================");
  Serial.println("READY");
}

// ============================================================
// MAIN LOOP
// ============================================================
void loop() {
  // Read commands from Raspberry Pi
  while (Serial.available()) {
    String cmd = Serial.readStringUntil('\n');
    cmd.trim();
    cmd.toUpperCase();
    if (cmd.length() == 0) continue;
    lastPiCommand = millis();
    handleCommand(cmd);
  }

  // Watchdog — stop if Pi disconnects
  if (millis() - lastPiCommand > PI_WATCHDOG_TIMEOUT) {
    if (currentMotion != STOPPED || bladeOn) {
      stopMotors();
      bladeOff();
      Serial.println("WATCHDOG_STOP");
    }
  }

  // Ultrasonic safety check
  UltrasonicData d = readAllUltrasonic();
  bool obstacle =
    (d.front > 0 && d.front < FRONT_STOP_DISTANCE) ||
    (d.left  > 0 && d.left  < SIDE_STOP_DISTANCE)  ||
    (d.right > 0 && d.right < SIDE_STOP_DISTANCE);

  if (obstacle) {
    if (currentMotion != STOPPED) {
      stopMotors();
      Serial.print("ULTRASONIC_STOP F=");
      Serial.print(d.front);
      Serial.print(" L=");
      Serial.print(d.left);
      Serial.print(" R=");
      Serial.println(d.right);
    }
    bladeOff();
  }

  delay(20);
}

// ============================================================
// COMMAND HANDLER
// ============================================================
void handleCommand(String cmd) {

  if (cmd == "PING") {
    Serial.println("PONG");
    return;
  }

  if (cmd == "STATUS") {
    sendStatus();
    return;
  }

  if (cmd == "FORWARD") {
    if (frontClear()) {
      changeMotion(FORWARD);
      Serial.println("OK FORWARD");
    } else {
      stopMotors(); bladeOff();
      Serial.println("BLOCKED FRONT");
    }
    return;
  }

  if (cmd == "BACKWARD" || cmd == "REVERSE") {
    if (rearClear()) {
      changeMotion(BACKWARD);
      Serial.println("OK BACKWARD");
    } else {
      stopMotors(); bladeOff();
      Serial.println("BLOCKED REVERSE");
    }
    return;
  }

  if (cmd == "LEFT") {
    if (leftClear()) {
      changeMotion(LEFT);
      Serial.println("OK LEFT");
    } else {
      stopMotors(); bladeOff();
      Serial.println("BLOCKED LEFT");
    }
    return;
  }

  if (cmd == "RIGHT") {
    if (rightClear()) {
      changeMotion(RIGHT);
      Serial.println("OK RIGHT");
    } else {
      stopMotors(); bladeOff();
      Serial.println("BLOCKED RIGHT");
    }
    return;
  }

  if (cmd == "STOP" || cmd == "MOVE_STOP") {
    stopMotors();
    bladeOff();
    Serial.println("OK STOP");
    return;
  }

  if (cmd == "BLADE_ON") {
    UltrasonicData d = readAllUltrasonic();
    bool safe =
      currentMotion != STOPPED &&
      d.front > FRONT_STOP_DISTANCE &&
      d.left  > SIDE_STOP_DISTANCE  &&
      d.right > SIDE_STOP_DISTANCE;

    if (safe) {
      digitalWrite(RELAY_PIN, HIGH);
      bladeOn = true;
      Serial.println("OK BLADE ON");
    } else {
      bladeOff();
      Serial.println("BLADE_BLOCKED");
    }
    return;
  }

  if (cmd == "BLADE_OFF") {
    bladeOff();
    Serial.println("OK BLADE OFF");
    return;
  }

  if (cmd == "ESTOP") {
    stopMotors();
    bladeOff();
    Serial.println("OK ESTOP");
    return;
  }

  if (cmd.startsWith("SET_SPEED")) {
    int separator = cmd.indexOf(' ');
    if (separator > 0) {
      int percent = cmd.substring(separator + 1).toInt();
      percent    = constrain(percent, 0, 100);
      motorSpeed = map(percent, 0, 100, 0, 255);
      Serial.print("OK SPEED ");
      Serial.println(percent);
    } else {
      Serial.println("ERROR SPEED");
    }
    return;
  }

  Serial.print("UNKNOWN COMMAND: ");
  Serial.println(cmd);
}

// ============================================================
// SAFE DIRECTION CHANGE
// ============================================================
void changeMotion(MotionState newMotion) {
  if (newMotion == currentMotion) return;

  stopMotors();

  if (newMotion == STOPPED) return;

  bool reversing =
    (currentMotion == FORWARD  && newMotion == BACKWARD) ||
    (currentMotion == BACKWARD && newMotion == FORWARD);

  if (reversing)
    delay(REVERSE_DELAY);
  else
    delay(DIRECTION_CHANGE_DELAY);

  // Safety check after delay
  UltrasonicData d = readAllUltrasonic();
  if (d.front > 0 && d.front < FRONT_STOP_DISTANCE) {
    bladeOff();
    Serial.println("MOVE_CANCELLED_FRONT");
    return;
  }

  switch (newMotion) {
    case FORWARD:  moveForward();  break;
    case BACKWARD: moveBackward(); break;
    case LEFT:     turnLeft();     break;
    case RIGHT:    turnRight();    break;
    default:       stopMotors();   break;
  }
}

// ============================================================
// MOTOR SPEED
// ============================================================
void setMotorSpeed(int leftSpeed, int rightSpeed) {
  leftSpeed  = constrain(leftSpeed,  0, 255);
  rightSpeed = constrain(rightSpeed, 0, 255);
  ledcWrite(L_ENA, leftSpeed);
  ledcWrite(L_ENB, leftSpeed);
  ledcWrite(R_ENA, rightSpeed);
  ledcWrite(R_ENB, rightSpeed);
}

// ============================================================
// STOP
// ============================================================
void stopMotors() {
  digitalWrite(L_IN1, LOW); digitalWrite(L_IN2, LOW);
  digitalWrite(L_IN3, LOW); digitalWrite(L_IN4, LOW);
  digitalWrite(R_IN1, LOW); digitalWrite(R_IN2, LOW);
  digitalWrite(R_IN3, LOW); digitalWrite(R_IN4, LOW);
  setMotorSpeed(0, 0);
  currentMotion = STOPPED;
}

// ============================================================
// FORWARD
// ============================================================
void moveForward() {
  digitalWrite(L_IN1, HIGH); digitalWrite(L_IN2, LOW);
  digitalWrite(L_IN3, HIGH); digitalWrite(L_IN4, LOW);
  digitalWrite(R_IN1, HIGH); digitalWrite(R_IN2, LOW);
  digitalWrite(R_IN3, HIGH); digitalWrite(R_IN4, LOW);
  setMotorSpeed(motorSpeed, motorSpeed);
  currentMotion = FORWARD;
}

// ============================================================
// BACKWARD
// ============================================================
void moveBackward() {
  digitalWrite(L_IN1, LOW); digitalWrite(L_IN2, HIGH);
  digitalWrite(L_IN3, LOW); digitalWrite(L_IN4, HIGH);
  digitalWrite(R_IN1, LOW); digitalWrite(R_IN2, HIGH);
  digitalWrite(R_IN3, LOW); digitalWrite(R_IN4, HIGH);
  setMotorSpeed(motorSpeed, motorSpeed);
  currentMotion = BACKWARD;
}

// ============================================================
// LEFT
// ============================================================
void turnLeft() {
  digitalWrite(L_IN1, LOW);  digitalWrite(L_IN2, HIGH);
  digitalWrite(L_IN3, LOW);  digitalWrite(L_IN4, HIGH);
  digitalWrite(R_IN1, HIGH); digitalWrite(R_IN2, LOW);
  digitalWrite(R_IN3, HIGH); digitalWrite(R_IN4, LOW);
  setMotorSpeed(motorSpeed, motorSpeed);
  currentMotion = LEFT;
}

// ============================================================
// RIGHT
// ============================================================
void turnRight() {
  digitalWrite(L_IN1, HIGH); digitalWrite(L_IN2, LOW);
  digitalWrite(L_IN3, HIGH); digitalWrite(L_IN4, LOW);
  digitalWrite(R_IN1, LOW);  digitalWrite(R_IN2, HIGH);
  digitalWrite(R_IN3, LOW);  digitalWrite(R_IN4, HIGH);
  setMotorSpeed(motorSpeed, motorSpeed);
  currentMotion = RIGHT;
}

// ============================================================
// BLADE OFF
// ============================================================
void bladeOff() {
  digitalWrite(RELAY_PIN, LOW);
  bladeOn = false;
}

// ============================================================
// ULTRASONIC READ
// ============================================================
float readUltrasonic(int trigPin, int echoPin) {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  unsigned long duration = pulseIn(echoPin, HIGH, ULTRASONIC_TIMEOUT);
  if (duration == 0) return 999.0;
  return (duration * 0.0343) / 2.0;
}

// ============================================================
// READ ALL 3 SENSORS
// ============================================================
UltrasonicData readAllUltrasonic() {
  UltrasonicData d;
  d.front = readUltrasonic(FRONT_TRIG, FRONT_ECHO);
  delay(5);
  d.left  = readUltrasonic(LEFT_TRIG,  LEFT_ECHO);
  delay(5);
  d.right = readUltrasonic(RIGHT_TRIG, RIGHT_ECHO);
  return d;
}

// ============================================================
// CLEAR CHECKS
// ============================================================
bool frontClear() {
  float d = readUltrasonic(FRONT_TRIG, FRONT_ECHO);
  return d == 999.0 || d >= FRONT_STOP_DISTANCE;
}

bool leftClear() {
  float d = readUltrasonic(LEFT_TRIG, LEFT_ECHO);
  return d == 999.0 || d >= SIDE_STOP_DISTANCE;
}

bool rightClear() {
  float d = readUltrasonic(RIGHT_TRIG, RIGHT_ECHO);
  return d == 999.0 || d >= SIDE_STOP_DISTANCE;
}

bool rearClear() {
  return true; // no rear sensor
}

// ============================================================
// STATUS
// ============================================================
void sendStatus() {
  UltrasonicData d = readAllUltrasonic();

  Serial.print("STATE:");
  switch (currentMotion) {
    case FORWARD:  Serial.print("FORWARD");  break;
    case BACKWARD: Serial.print("BACKWARD"); break;
    case LEFT:     Serial.print("LEFT");     break;
    case RIGHT:    Serial.print("RIGHT");    break;
    default:       Serial.print("STOP");     break;
  }

  Serial.print(",BLADE:");
  Serial.print(bladeOn ? "ON" : "OFF");
  Serial.print(",F:");  Serial.print(d.front, 1);
  Serial.print(",L:");  Serial.print(d.left,  1);
  Serial.print(",R:");  Serial.println(d.right, 1);
}

