// ROBOT STATE
// ============================================================
enum MotionState { STOPPED, FORWARD, BACKWARD, LEFT, RIGHT };
MotionState currentMotion = STOPPED;

bool bladeOn = false;
unsigned long lastPiCommand = 0;

struct UltrasonicData {
  float front;
  float left;
  float right;
