    if (leftClear()) {
      changeMotion(LEFT);
      Serial.println("OK LEFT");
    } else {
      stopMotors(); bladeOff();
      Serial.println("BLOCKED LEFT");
    }
    return;
  }

  if (cmd == "RIGHT") {
    if (rightClear()) {
      changeMotion(RIGHT);
      Serial.println("OK RIGHT");
    } else {
      stopMotors(); bladeOff();
      Serial.println("BLOCKED RIGHT");
    }
    return;
  }

  if (cmd == "STOP" || cmd == "MOVE_STOP") {
    stopMotors();
    bladeOff();
    Serial.println("OK STOP");
    return;
  }

