  if (newMotion == currentMotion) return;

  stopMotors();

  if (newMotion == STOPPED) return;

  bool reversing =
    (currentMotion == FORWARD  && newMotion == BACKWARD) ||
    (currentMotion == BACKWARD && newMotion == FORWARD);

  if (reversing)
    delay(REVERSE_DELAY);
  else
    delay(DIRECTION_CHANGE_DELAY);

  // Safety check after delay
  UltrasonicData d = readAllUltrasonic();
  if (d.front > 0 && d.front < FRONT_STOP_DISTANCE) {
    bladeOff();
    Serial.println("MOVE_CANCELLED_FRONT");
    return;
  }

  switch (newMotion) {
    case FORWARD:  moveForward();  break;
    case BACKWARD: moveBackward(); break;
    case LEFT:     turnLeft();     break;
    case RIGHT:    turnRight();    break;
    default:       stopMotors();   break;
  }
}

// ============================================================
// MOTOR SPEED
// ============================================================
void setMotorSpeed(int leftSpeed, int rightSpeed) {
  leftSpeed  = constrain(leftSpeed,  0, 255);
  rightSpeed = constrain(rightSpeed, 0, 255);
  ledcWrite(L_ENA, leftSpeed);
  ledcWrite(L_ENB, leftSpeed);
  ledcWrite(R_ENA, rightSpeed);
  ledcWrite(R_ENB, rightSpeed);
}

// ============================================================
// STOP
// ============================================================
void stopMotors() {
  digitalWrite(L_IN1, LOW); digitalWrite(L_IN2, LOW);
  digitalWrite(L_IN3, LOW); digitalWrite(L_IN4, LOW);
  digitalWrite(R_IN1, LOW); digitalWrite(R_IN2, LOW);
  digitalWrite(R_IN3, LOW); digitalWrite(R_IN4, LOW);
  setMotorSpeed(0, 0);
  currentMotion = STOPPED;
}

// ============================================================
// FORWARD
// ============================================================
void moveForward() {
  digitalWrite(L_IN1, HIGH); digitalWrite(L_IN2, LOW);
  digitalWrite(L_IN3, HIGH); digitalWrite(L_IN4, LOW);
  digitalWrite(R_IN1, HIGH); digitalWrite(R_IN2, LOW);
  digitalWrite(R_IN3, HIGH); digitalWrite(R_IN4, LOW);
  setMotorSpeed(motorSpeed, motorSpeed);
  currentMotion = FORWARD;
}

// ============================================================
// BACKWARD
// ============================================================
void moveBackward() {
  digitalWrite(L_IN1, LOW); digitalWrite(L_IN2, HIGH);
  digitalWrite(L_IN3, LOW); digitalWrite(L_IN4, HIGH);
  digitalWrite(R_IN1, LOW); digitalWrite(R_IN2, HIGH);
  digitalWrite(R_IN3, LOW); digitalWrite(R_IN4, HIGH);
  setMotorSpeed(motorSpeed, motorSpeed);
  currentMotion = BACKWARD;
}

// ============================================================
// LEFT
// ============================================================
void turnLeft() {
  digitalWrite(L_IN1, LOW);  digitalWrite(L_IN2, HIGH);
  digitalWrite(L_IN3, LOW);  digitalWrite(L_IN4, HIGH);
  digitalWrite(R_IN1, HIGH); digitalWrite(R_IN2, LOW);
  digitalWrite(R_IN3, HIGH); digitalWrite(R_IN4, LOW);
  setMotorSpeed(motorSpeed, motorSpeed);
  currentMotion = LEFT;
}

// ============================================================
// RIGHT
// ============================================================
void turnRight() {
  digitalWrite(L_IN1, HIGH); digitalWrite(L_IN2, LOW);
  digitalWrite(L_IN3, HIGH); digitalWrite(L_IN4, LOW);
  digitalWrite(R_IN1, LOW);  digitalWrite(R_IN2, HIGH);
  digitalWrite(R_IN3, LOW);  digitalWrite(R_IN4, HIGH);
  setMotorSpeed(motorSpeed, motorSpeed);
  currentMotion = RIGHT;
}

// ============================================================
// BLADE OFF
// ============================================================
void bladeOff() {
  digitalWrite(RELAY_PIN, LOW);
  bladeOn = false;
}

// ============================================================
// ULTRASONIC READ
// ============================================================
float readUltrasonic(int trigPin, int echoPin) {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  unsigned long duration = pulseIn(echoPin, HIGH, ULTRASONIC_TIMEOUT);
  if (duration == 0) return 999.0;
  return (duration * 0.0343) / 2.0;
}

// ============================================================
// READ ALL 3 SENSORS
// ============================================================
UltrasonicData readAllUltrasonic() {
  UltrasonicData d;
  d.front = readUltrasonic(FRONT_TRIG, FRONT_ECHO);
  delay(5);
  d.left  = readUltrasonic(LEFT_TRIG,  LEFT_ECHO);
  delay(5);
  d.right = readUltrasonic(RIGHT_TRIG, RIGHT_ECHO);
  return d;
}

// ============================================================
// CLEAR CHECKS
// ============================================================
bool frontClear() {
  float d = readUltrasonic(FRONT_TRIG, FRONT_ECHO);
  return d == 999.0 || d >= FRONT_STOP_DISTANCE;
}

bool leftClear() {
  float d = readUltrasonic(LEFT_TRIG, LEFT_ECHO);
  return d == 999.0 || d >= SIDE_STOP_DISTANCE;
}

bool rightClear() {
  float d = readUltrasonic(RIGHT_TRIG, RIGHT_ECHO);
  return d == 999.0 || d >= SIDE_STOP_DISTANCE;
}

bool rearClear() {
  return true; // no rear sensor
}

// ============================================================
// STATUS
// ============================================================
void sendStatus() {
  UltrasonicData d = readAllUltrasonic();

  Serial.print("STATE:");
  switch (currentMotion) {
    case FORWARD:  Serial.print("FORWARD");  break;
    case BACKWARD: Serial.print("BACKWARD"); break;
    case LEFT:     Serial.print("LEFT");     break;
    case RIGHT:    Serial.print("RIGHT");    break;
    default:       Serial.print("STOP");     break;
  }

  Serial.print(",BLADE:");
  Serial.print(bladeOn ? "ON" : "OFF");
  Serial.print(",F:");  Serial.print(d.front, 1);
  Serial.print(",L:");  Serial.print(d.left,  1);
  Serial.print(",R:");  Serial.println(d.right, 1);
}
